#!/usr/bin/env node
// skillstate Claude Code hook — UserPromptSubmit (generated by @skillstate/claude).
// Self-contained CommonJS: reads one hook JSON document on stdin,
// resolves the state from the SESSION cwd, and emits
// { hookSpecificOutput: { hookEventName, additionalContext } }.
// INERT without state: no state file → stdout is "{}" (no context
// is added; hooks never create state files).
// State file (per-project resolver): <cwd>/.skillstate/skillstate.json (global bucket when cwd === home)
'use strict';
const fs = require("fs");
const os = require("os");
const path = require("path");

const HOOK_EVENT_NAME = "UserPromptSubmit";
const INTERRUPTED_SESSION_NOTE = "\nPrevious session was interrupted; state preserved at <path>; review progress/blockers before continuing.";

function isPlainObject(value) {
    return typeof value === 'object' && value !== null && !Array.isArray(value);
}

function resolveAgentIdFromSession(sessionId) {
    if (typeof sessionId !== 'string' || sessionId.length === 0)
        return '';
    return sanitizeAgentId(sessionId.slice(0, 8));
}

function sanitizeAgentId(agentId) {
    return agentId
        .replace(/[^A-Za-z0-9_-]+/g, '-')
        .replace(/^-+|-+$/g, '')
        .slice(0, 64);
}

function resolveStatePathForCwd(cwd, home, agentId) {
    const normalize = (p) => {
        const isAbsolute = p.startsWith('/');
        const segments = [];
        for (const segment of p.split('/')) {
            if (segment === '' || segment === '.')
                continue;
            if (segment === '..') {
                if (segments.length > 0 && segments[segments.length - 1] !== '..') {
                    segments.pop();
                }
                else if (!isAbsolute) {
                    segments.push('..');
                }
                continue;
            }
            segments.push(segment);
        }
        return (isAbsolute ? '/' : '') + segments.join('/');
    };
    const rootless = (p) => (p === '/' ? '' : p);
    const resolvedCwd = normalize(cwd);
    const resolvedHome = home === undefined || home === null ? '' : normalize(home);
    const agent = typeof agentId === 'string' && agentId.length > 0 ? sanitizeAgentId(agentId) : '';
    const base = resolvedCwd === resolvedHome
        ? `${rootless(resolvedHome)}/.skillstate/global`
        : `${rootless(resolvedCwd)}/.skillstate`;
    if (agent.length > 0) {
        return `${base}/agents/${agent}/skillstate.json`;
    }
    return `${base}/skillstate.json`;
}

function readStateEnvelope(statePath, readFile) {
    try {
        const parsed = JSON.parse(readFile(statePath));
        if (isPlainObject(parsed)) {
            if (isPlainObject(parsed.state)) {
                return parsed.state;
            }
            return parsed;
        }
    }
    catch {
        // Missing or corrupt state file — fall back to the empty state.
    }
    return {};
}

function saveStateEnvelope(statePath, state, writeFile) {
    writeFile(statePath, `${JSON.stringify({ version: 1, state }, null, 2)}\n`);
}

function mergePatch(state, patch) {
    const result = { ...state };
    for (const key of Object.keys(patch)) {
        const value = patch[key];
        if (value === null) {
            delete result[key];
        }
        else if (isPlainObject(value) && isPlainObject(result[key])) {
            result[key] = mergePatch(result[key], value);
        }
        else {
            result[key] = value;
        }
    }
    return result;
}

function readResponseText(response) {
    if (typeof response === 'string')
        return response;
    if (isPlainObject(response)) {
        if (typeof response['content'] === 'string')
            return response['content'];
        if (typeof response['text'] === 'string')
            return response['text'];
        return JSON.stringify(response);
    }
    return response === null || response === undefined ? '' : String(response);
}

function findFencedPatch(text) {
    const match = text.match(/```json\s*\n?([\s\S]*?)\n?\s*```/) ||
        text.match(/```json\s*\n?([\s\S]+)$/);
    if (!match)
        return { absent: true };
    try {
        const parsed = JSON.parse(match[1]);
        if (isPlainObject(parsed) && isPlainObject(parsed['state_patch'])) {
            return { patch: parsed['state_patch'] };
        }
    }
    catch {
        // Malformed fenced JSON — report an invalid patch attempt.
    }
    return { invalid: true };
}

function findRawPatch(text) {
    const trimmed = text.trim();
    const candidates = [];
    try {
        candidates.push(JSON.parse(trimmed));
    }
    catch {
        // Not a whole-text JSON object — try the braced slice below.
    }
    const first = trimmed.indexOf('{');
    const last = trimmed.lastIndexOf('}');
    if (first !== -1 && last > first) {
        try {
            candidates.push(JSON.parse(trimmed.slice(first, last + 1)));
        }
        catch {
            // The braced slice is not JSON either — no candidates left.
        }
    }
    for (const candidate of candidates) {
        if (isPlainObject(candidate)) {
            if (isPlainObject(candidate['state_patch'])) {
                return { patch: candidate['state_patch'] };
            }
            if (Object.prototype.hasOwnProperty.call(candidate, 'state_patch')) {
                return { invalid: true };
            }
        }
    }
    return { absent: true };
}

function sleepSync(ms) {
    try {
        Atomics.wait(new Int32Array(new SharedArrayBuffer(4)), 0, 0, ms);
        return;
    }
    catch (error) {
        // Atomics.wait unavailable in this host — spin below.
    }
    const end = Date.now() + ms;
    while (Date.now() < end) {
        // Spin — hook scripts must stay synchronous.
    }
}

function lockStateWrite(statePath, fs, fn) {
    const lockPath = `${statePath}.lock`;
    const ttl = 10_000;
    const retries = 40;
    const dir = lockPath.replace(/\/[^/]+$/, '');
    try {
        fs.mkdirSync(dir);
    }
    catch (error) {
        // Exists already — only the lockfile itself must be exclusive.
    }
    let acquired = false;
    for (let attempt = 0; attempt < retries; attempt++) {
        try {
            fs.closeSync(fs.openSync(lockPath, 'wx'));
            acquired = true;
            break;
        }
        catch (error) {
            let mtimeMs = 0;
            try {
                mtimeMs = fs.statSync(lockPath).mtimeMs;
            }
            catch (error) {
                // Vanished between the failed create and the stat — retry at once.
            }
            if (Date.now() - mtimeMs > ttl) {
                try {
                    fs.unlinkSync(lockPath);
                }
                catch (error) {
                    // Another waiter removed it first — retry from the top.
                }
            }
            else {
                sleepSync(50);
            }
        }
    }
    if (!acquired) {
        throw new Error(`skillstate: could not acquire the state lock: ${lockPath}`);
    }
    try {
        return fn();
    }
    finally {
        try {
            fs.unlinkSync(lockPath);
        }
        catch (error) {
            // Lock already removed (stale takeover raced us) — nothing to release.
        }
    }
}

function stateFileExists(statePath, fs) {
    try {
        fs.accessSync(statePath);
        return true;
    }
    catch {
        return false;
    }
}

function readSessionMetaStatus(metaPath, readFile) {
    try {
        const parsed = JSON.parse(readFile(metaPath));
        if (isPlainObject(parsed) && typeof parsed.status === 'string') {
            return parsed.status;
        }
    }
    catch (error) {
        // Missing or corrupt sidecar — no lifecycle marker.
    }
    return null;
}

let raw = "";
process.stdin.setEncoding("utf-8");
process.stdin.on("data", (chunk) => { raw += chunk; });
process.stdin.on("end", () => {
  let cwd = process.cwd();
  let agentId = "";
  try {
    const input = JSON.parse(raw);
    if (typeof input.cwd === "string" && input.cwd.length > 0) {
      cwd = input.cwd;
    }
    agentId = resolveAgentIdFromSession(input.session_id);
  } catch (error) {}
  const statePath = resolveStatePathForCwd(
    path.resolve(cwd),
    path.resolve(os.homedir()),
    agentId,
  );
  if (!stateFileExists(statePath, fs)) {
    process.stdout.write("{}");
    return;
  }
  const state = readStateEnvelope(statePath, (p) => fs.readFileSync(p, "utf-8"));
  let contextSuffix = "\nHistory is not reliable. Persist anything you need via the skillstate MCP tools (state.summary / state.patch) or a fenced ```json state_patch block.";
  const output = {
    hookSpecificOutput: {
      hookEventName: HOOK_EVENT_NAME,
      additionalContext: "Current skill state (JSON): " + JSON.stringify(state)
        + contextSuffix,
    },
  };
  process.stdout.write(JSON.stringify(output));
});
